<?php
require dirname(__DIR__).'/bootstrap.php';
use App\Core\Database;use App\Core\Csrf;
function runSqlBatch($pdo,string $sql): void {foreach(preg_split('/;\s*(?:\r?\n|$)/',$sql) as $stmt){$stmt=trim($stmt);if($stmt!=='')$pdo->exec($stmt);}}
$csrf=Csrf::token();$lock=dirname(__DIR__).'/storage/install.lock';$message='';$error='';$locked=is_file($lock);if(!$locked){try{$check=Database::connection();$locked=(int)$check->query('SELECT COUNT(*) FROM users')->fetchColumn()>0;}catch(Throwable $e){$locked=false;}}
if($_SERVER['REQUEST_METHOD']==='POST'&&!$locked){try{if(!Csrf::validate($_POST['_csrf']??null))throw new RuntimeException('Sesi setup tidak valid. Muat ulang halaman.');$pdo=Database::connection();$schema=file_get_contents(dirname(__DIR__).'/database/schema.sql');$seed=file_get_contents(dirname(__DIR__).'/database/seed.sql');runSqlBatch($pdo,$schema);runSqlBatch($pdo,$seed);$role=(int)$pdo->query("SELECT id FROM roles WHERE slug='superadmin'")->fetchColumn();$name=trim($_POST['name']??'Administrator');$email=strtolower(trim($_POST['email']??''));$password=(string)($_POST['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8)throw new RuntimeException('Email/password admin tidak valid.');$pdo->prepare('INSERT INTO users(role_id,name,email,password,status) VALUES(?,?,?,?,?)')->execute([$role,$name,$email,password_hash($password,PASSWORD_DEFAULT),'active']);file_put_contents($lock,date(DATE_ATOM)."\nInstalled by setup.php\n");$message='Instalasi selesai. Setup sekarang terkunci. Login menggunakan akun Super Admin yang baru dibuat.';$locked=true;}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Setup Kedai Bara Pro</title><link rel="stylesheet" href="assets/css/app.css"></head><body class="login-body"><div class="login-card"><div class="login-brand"><div class="brand-badge">KB</div><div><h1>Setup Kedai Bara Pro</h1><p>Fresh installer database & Super Admin</p></div></div><?php if($message):?><div class="alert success"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="alert danger"><?=htmlspecialchars($error)?></div><?php endif;?><?php if($locked):?><div class="alert success"><strong>Installed.</strong><br>Installer dikunci oleh <code>storage/install.lock</code> agar database tidak ter-reset tanpa sengaja.</div><a class="btn primary full" href="index.php?page=login">Buka Login</a><?php else:?><form method="post" class="stack"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf)?>"><label>Nama Admin<input class="control" name="name" value="Administrator" required></label><label>Email<input class="control" type="email" name="email" value="admin@kedaibara.local" required></label><label>Password<input class="control" type="password" name="password" minlength="8" required></label><button class="btn primary" type="submit">Install Database Fresh</button></form><p class="muted small">Pastikan <code>config/database.php</code> benar dan database kosong telah dibuat. Installer ini menggunakan schema final dan tidak membutuhkan migration.</p><?php endif;?></div></body></html>
